@Embeddable public class TranCategoryBalanceId implements Serializable { @Column(name="acct_id") Long acctId; @Column(name="type_cd",length=2) String typeCd; @Column(name="cat_cd") Integer catCd; public TranCategoryBalanceId(){} public TranCategoryBalanceId(Long a,String t,Integer c){acctId=a;typeCd=t;catCd=c;} public Long getAcctId(){return acctId;} public void setAcctId(Long v){acctId=v;} public String getTypeCd(){return typeCd;} public void setTypeCd(String v){typeCd=v;} public Integer getCatCd(){return catCd;} public void setCatCd(Integer v){catCd=v;} @Override public boolean equals(Object o){return o instanceof TranCategoryBalanceId k&&java.util.Objects.equals(acctId,k.acctId)&&java.util.Objects.equals(typeCd,k.typeCd)&&java.util.Objects.equals(catCd,k.catCd);} @Override public int hashCode(){return java.util.Objects.hash(acctId,typeCd,catCd);} }
